    int maxHeight = 0;
    while (!st.empty()) {
        const Node* node = st.top();
        st.pop();
        if (!node) continue;
        maxHeight = std::max(maxHeight, 1 + std::max(height(node->left), height(node->right)));
        st.push(node->right);
        st.push(node->left);
    }
    return maxHeight;
}"
